/**
 * Typed wrapper around the Emscripten output generated by
 * `scripts/build-espeak-ng.js` (espeak-ng 1.52.0 + vendor/espeak-ng-bridge,
 * compiled to plain JavaScript, no WebAssembly).
 *
 * Keep this file small and hand-maintained. The large sibling file
 * `espeakng-runtime.js` is generated and should not be edited manually.
 *
 * espeak-ng is GPL-3.0-or-later, and so is the generated runtime.
 */
interface EspeakNgFS {
  /** Create a directory and its parents inside Emscripten MEMFS. */
  mkdirTree(path: string): void;
  /** Write a data file into Emscripten MEMFS. */
  writeFile(path: string, data: Uint8Array): void;
}

export interface EspeakNgModule {
  FS: EspeakNgFS;
  /** Convert a NUL-terminated UTF-8 string pointer from the Emscripten heap. */
  UTF8ToString(ptr: number): string;
  /** Write `str` as NUL-terminated UTF-8 at `ptr` (at most `maxBytes` bytes). */
  stringToUTF8(str: string, ptr: number, maxBytes: number): number;
  /** UTF-8 length of `str` in bytes, without the NUL terminator. */
  lengthBytesUTF8(str: string): number;
  _malloc(size: number): number;
  _free(ptr: number): void;
  /** espeak_Initialize(AUDIO_OUTPUT_SYNCHRONOUS, 0, path, 0): 0 on success, else an espeak_ng_STATUS. */
  _kt_espeak_initialize(dataPathPtr: number): number;
  /** espeak_ListVoices(NULL); espeak_SetVoiceByName(identifier): 0 on success. */
  _kt_espeak_set_voice(identifierPtr: number): number;
  /** phonemizer's EspeakWrapper.text_to_phonemes loop; pointer owned by the bridge, 0 when out of memory. */
  _kt_espeak_text_to_phonemes(textPtr: number, phonemeMode: number): number;
  /** espeak_Info(NULL): the espeak-ng version string. */
  _kt_espeak_version(): number;
}

type EspeakNgModuleFactory = (options?: Record<string, unknown>) => Promise<EspeakNgModule>;

declare const require: (path: string) => unknown;

const createEspeakNgModule = require('./espeakng-runtime') as EspeakNgModuleFactory;

export default createEspeakNgModule;
